import {formatDate} from './model.js';
import {api} from './auth.js';
import {uid,today,validDate} from './model.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rub=v=>v===null?'—':(v/100).toLocaleString('ru-RU',{maximumFractionDigits:2})+' ₽';
const sum=(rows,key)=>rows.reduce((n,x)=>n+(x[key]??0),0);
const money=v=>{v=String(v).trim().replace(/[\s₽]/g,'').replace(',','.');if(!v)return null;if(!/^\d+(\.\d{1,2})?$/.test(v)||Number(v)>1e9)throw Error('Введите сумму от 0 до 1 млрд ₽, не более двух знаков после запятой.');return Math.round(Number(v)*100);};
const signedMoney=v=>String(v).trim().startsWith('-')?-money(String(v).trim().slice(1)):money(v);
const num=v=>{v=String(v).trim().replace(',','.');if(!v)return null;const n=Number(v);if(!Number.isFinite(n)||n<0||n>1e12)throw Error('Проверьте показание.');return n;};
const monthName=p=>new Date(p+'-01T12:00:00').toLocaleDateString('ru-RU',{month:'long'});
const current=()=>{const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Novosibirsk',year:'numeric',month:'2-digit'}).formatToParts(new Date());return p.find(x=>x.type==='year').value+'-'+p.find(x=>x.type==='month').value;};
const btn=(action,label,attrs='')=>`<button data-zkh="${action}" ${attrs}>${label}</button>`;
const input=(value,attrs='')=>`<input ${attrs} value="${esc(value)}" data-original="${esc(value)}">`;
const field=(label,name,value,type='text',attrs='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
export async function startZkh(root,user){
 for(const href of ['/finance.css','/zkh.css']){if(!document.querySelector(`link[href="${href}"]`)){const l=document.createElement('link');l.rel='stylesheet';l.href=href;document.head.append(l);}}
 let state=await api('/api/zkh'),data=state.data,revision=state.revision,tab='overview',objectId=data.objects.find(x=>!x.archived)?.id||'',mode='payments',year=Number(current().slice(0,4)),month=current().slice(5),dirty=false,busy=false,error='',notice='',view='table';
 const desktop=matchMedia('(min-width:900px)'),tableMode=()=>desktop.matches&&view==='table',modal=document.getElementById('modal');
 const periods=()=>Array.from({length:12},(_,i)=>`${year}-${String(i+1).padStart(2,'0')}`).filter(p=>month==='all'||p.slice(5)===month);
 const inPeriod=p=>p.startsWith(year+'-')&&(month==='all'||p===`${year}-${month}`);
 const services=owner=>data.services.filter(x=>x.objectId===owner);
 const paymentRows=(service,period)=>data.payments.filter(x=>x.serviceId===service&&x.month===period);
 const readings=(meter,period)=>data.readings.filter(x=>x.meterId===meter&&x.month===period).sort((a,b)=>(b.date||b.month).localeCompare(a.date||a.month));
 function mark(){dirty=true;root.querySelector('[data-save-status]').textContent='Есть несохранённые изменения';}
 async function persist(next,path='/api/zkh',extra={}){const result=await api(path,{method:path==='/api/zkh'?'PUT':'POST',body:JSON.stringify({revision,data:next,...extra})});data=result.data;revision=result.revision;dirty=false;error='';notice='Сохранено';if(!data.objects.some(x=>x.id===objectId))objectId=data.objects.find(x=>!x.archived)?.id||'';render();}
 function download(value,name){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(value)],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function form(title,body,label,apply){modal.innerHTML=`<div class="modal-header"><h2>${title}</h2><button data-close aria-label="Закрыть">✕</button></div><form class="modal-body">${body}<p class="error" role="alert"></p><div class="modal-buttons"><button type="button" data-close>Отмена</button><button class="primary" type="submit">${label}</button></div></form>`;modal.showModal();modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>modal.close());modal.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const f=new FormData(e.target),next=structuredClone(data);await apply(f,next);modal.close();}catch(err){modal.querySelector('.error').textContent=err.message;}finally{b.disabled=false;}};}
 const toolbar=()=>`<div class="grid-toolbar"><span data-save-status role="status">Все изменения сохранены</span><div>${btn('cancel','Отменить изменения')}${btn('save','Сохранить изменения','class="primary"')}</div></div><p class="footnote">Tab — следующее поле. Пустая сумма означает «не указано», 0 — нулевую оплату. Для нескольких оплат за месяц подробности доступны в истории.</p>`;
 function overview(){const owner=data.objects.find(x=>x.id===objectId),all=data.payments.filter(x=>inPeriod(x.month)),fees=sum(all,'commission'),paid=sum(all,'amount'),tax=sum(data.taxes.filter(x=>inPeriod(x.date?.slice(0,7)||x.month)),'amount');return `<div class="fin-kpis">${[['Услуги',paid],['Комиссии',fees],['Налоги',tax],['Общий расход',paid+fees+tax]].map(([l,v])=>`<article class="panel"><span class="muted">${l}</span><strong>${rub(v)}</strong></article>`).join('')}</div><div class="zkh-object-grid">${[...data.objects].sort((a,b)=>Number(a.archived)-Number(b.archived)).map(o=>{const ids=new Set(services(o.id).map(x=>x.id)),rows=all.filter(x=>ids.has(x.serviceId));return `<article class="panel"><span class="muted">${esc(o.label)}${o.archived?' · архив':''}</span><h3>${esc(o.name)}</h3><p class="fin-metric">${rub(sum(rows,'amount')+sum(rows,'commission'))}</p><p class="muted">${rows.length} записей · комиссии ${rub(sum(rows,'commission'))}</p>${btn('open-object','Платежи',`data-id="${o.id}" class="secondary"`)}</article>`;}).join('')}</div>${!data.objects.length?'<section class="panel"><h3>Перенесите историю из Excel</h3><p class="footnote">Откройте «Ещё» и выберите подготовленный файл истории ЖКХ.</p></section>':''}<h3>Расходы по месяцам</h3><div class="finance-grid-wrap"><table class="finance-grid"><thead><tr><th>Месяц</th>${data.objects.map(o=>`<th>${esc(o.name)}</th>`).join('')}<th>Сервисы</th><th>Налоги</th><th>Всего</th></tr></thead><tbody>${periods().map(p=>{const rows=data.payments.filter(x=>x.month===p),values=[...data.objects.map(o=>{const ids=new Set(services(o.id).map(x=>x.id));return rows.filter(x=>ids.has(x.serviceId)).reduce((n,x)=>n+(x.amount||0)+(x.commission||0),0);}),rows.filter(x=>services('services').some(s=>s.id===x.serviceId)).reduce((n,x)=>n+(x.amount||0)+(x.commission||0),0),sum(data.taxes.filter(x=>(x.date?.slice(0,7)||x.month)===p),'amount')];return `<tr><th>${monthName(p)}</th>${[...values,values.reduce((a,b)=>a+b,0)].map(v=>`<td>${rub(v)}</td>`).join('')}</tr>`;}).join('')}</tbody></table></div><p class="footnote">Доход самозанятости в расходах не учитывается. Отсутствие записи не означает задолженность.</p>`;}
 function paymentsView(owner){const cols=services(owner);if(!cols.length)return `<section class="panel"><p>Для этого объекта пока нет услуг.</p>${btn('new-service','Добавить услугу',`data-owner="${owner}" class="primary"`)}</section>`;
  const top=`<div class="row between"><h3>${owner==='services'?'Сервисы':'Платежи'}</h3><div>${btn('new-payment','＋ Оплата',`data-owner="${owner}" class="primary"`)}${btn('new-service','＋ Услуга',`data-owner="${owner}"`)}</div></div>`;
  if(!tableMode())return top+`<div class="zkh-service-grid">${cols.map(s=>{const rows=data.payments.filter(x=>x.serviceId===s.id&&inPeriod(x.month)).sort((a,b)=>b.month.localeCompare(a.month)||b.date.localeCompare(a.date));return `<article class="panel"><h3>${esc(s.name)}</h3><p class="fin-metric">${rows.length?rub(sum(rows,'amount')):'Нет записей'}</p><p class="muted">Комиссия ${rub(sum(rows,'commission'))}${s.autopay?' · отметка АП из Excel':''}</p>${btn('new-payment','Добавить оплату',`data-service="${s.id}" class="primary"`)}<details class="fin-payments"><summary>История · ${rows.length}</summary>${rows.map(x=>`<div class="fin-line"><span>${esc(x.month)} · ${formatDate(x.date)||'Дата не указана'}${x.source?.dateRaw&&!x.date?`<small>${esc(x.source.dateRaw)}</small>`:''}</span><span>${rub(x.amount)}${btn('edit-payment','Изменить',`data-id="${x.id}"`)}</span></div>`).join('')}</details></article>`;}).join('')}</div>`;
  return top+toolbar()+`<div class="finance-grid-wrap"><table class="finance-grid zkh-payment-grid"><thead><tr><th rowspan="2">Месяц</th>${cols.map(s=>`<th colspan="3">${esc(s.name)}</th>`).join('')}<th rowspan="2">Всего</th></tr><tr>${cols.map(()=>'<th>Сумма, ₽</th><th>Комиссия, ₽</th><th>Дата оплаты</th>').join('')}</tr></thead><tbody>${periods().map(p=>`<tr data-period="${p}"><th>${monthName(p)}</th>${cols.map(s=>{const rows=paymentRows(s.id,p),a=rows.some(x=>x.amount!==null)?sum(rows,'amount'):null,c=rows.some(x=>x.commission!==null)?sum(rows,'commission'):null;return `<td>${input(a===null?'':a/100,`data-payment="${s.id}" data-field="amount" aria-label="${p} ${esc(s.name)} сумма" inputmode="decimal"`)}${rows.length>1?btn('history',`${rows.length} оплат`, `data-service="${s.id}" data-period="${p}" class="textlink small"`):''}</td><td>${input(c===null?'':c/100,`data-payment="${s.id}" data-field="commission" aria-label="${p} ${esc(s.name)} комиссия" inputmode="decimal"`)}</td><td>${input(rows.length===1?rows[0].date:'',`type="date" data-payment="${s.id}" data-field="date" aria-label="${p} ${esc(s.name)} дата" ${rows.length>1?'disabled title="Даты нескольких оплат доступны в истории"':''}`)}</td>`;}).join('')}<td class="zkh-computed">${rub(cols.reduce((n,s)=>n+paymentRows(s.id,p).reduce((a,x)=>a+(x.amount||0)+(x.commission||0),0),0))}</td></tr>`).join('')}</tbody><tfoot><tr><th>Итого</th>${cols.map(s=>{const r=data.payments.filter(x=>x.serviceId===s.id&&inPeriod(x.month));return `<td>${rub(sum(r,'amount'))}</td><td>${rub(sum(r,'commission'))}</td><td></td>`;}).join('')}<td>${rub(data.payments.filter(x=>cols.some(s=>s.id===x.serviceId)&&inPeriod(x.month)).reduce((n,x)=>n+(x.amount||0)+(x.commission||0),0))}</td></tr></tfoot></table></div>`;
 }
 function consumption(meter,p,x){if(!x)return '—';const prior=data.readings.filter(r=>r.meterId===meter&&r.month<p).sort((a,b)=>b.month.localeCompare(a.month)||b.date.localeCompare(a.date))[0];if(!prior)return 'Нет предыдущего';const delta=x.value-prior.value;return delta<0?'Проверьте замену счётчика':delta.toLocaleString('ru-RU',{maximumFractionDigits:3});}
 function metersView(){const cols=data.meters.filter(x=>x.objectId===objectId);if(!cols.length)return `<section class="panel"><p>Для объекта пока нет счётчиков.</p>${btn('new-meter','Добавить счётчик','class="primary"')}</section>`;
  if(!tableMode())return `<div class="row between"><h3>Счётчики</h3>${btn('new-meter','＋ Счётчик')}</div><div class="zkh-service-grid">${cols.map(m=>`<article class="panel"><h3>${esc(m.name)}</h3>${periods().map(p=>{const x=readings(m.id,p)[0];return `<div class="fin-line"><span>${monthName(p)}<small>${formatDate(x?.date)||'Дата передачи не указана'}</small></span><span>${x?x.value.toLocaleString('ru-RU')+' '+esc(m.unit):'Нет показания'}${btn('reading','Заполнить',`data-meter="${m.id}" data-period="${p}"`)}</span></div><p class="footnote">Расход: ${consumption(m.id,p,x)} ${esc(m.unit)}</p>${readings(m.id,p).length>1?`<details class="fin-payments"><summary>Все показания месяца · ${readings(m.id,p).length}</summary>${readings(m.id,p).map(r=>`<div class="fin-line"><span>${r.value} · ${formatDate(r.date)||'Дата не указана'}</span>${btn('reading','Изменить',`data-meter="${m.id}" data-period="${p}" data-id="${r.id}"`)}</div>`).join('')}</details>`:''}`;}).join('')}</article>`).join('')}</div>`;
  return `<div class="row between"><h3>Показания счётчиков</h3>${btn('new-meter','＋ Счётчик')}</div>${toolbar()}<div class="finance-grid-wrap"><table class="finance-grid zkh-meter-grid"><thead><tr><th rowspan="2">Месяц</th>${cols.map(m=>`<th colspan="3">${esc(m.name)} · ${esc(m.unit)}</th>`).join('')}</tr><tr>${cols.map(()=>'<th>Показание</th><th>Дата передачи</th><th>Расход</th>').join('')}</tr></thead><tbody>${periods().map(p=>`<tr data-period="${p}"><th>${monthName(p)}</th>${cols.map(m=>{const x=readings(m.id,p)[0];return `<td>${input(x?.value??'',`data-meter="${m.id}" data-field="value" aria-label="${p} ${esc(m.name)} показание" inputmode="decimal"`)}</td><td>${input(x?.date||'',`data-meter="${m.id}" data-field="date" type="date" aria-label="${p} ${esc(m.name)} дата"`)}</td><td class="zkh-computed">${consumption(m.id,p,x)}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`;
 }
 const previousMonth=p=>{const y=Number(p.slice(0,4)),m=Number(p.slice(5));return `${m===1?y-1:y}-${String(m===1?12:m-1).padStart(2,'0')}`;};
 const taxPeriod=x=>x.taxIncomeMonth||(x.source?previousMonth(x.month):x.month);
 const taxConfirmed=x=>!!x.taxIncomeMonth||(x.month==='2026-03'&&x.amount===40000&&x.source?.sheet==='Сервисы и Налоги');
 function taxGroups(){const keys=new Set([...data.taxes.filter(x=>x.income!==null).map(x=>x.month),...data.taxes.filter(x=>x.amount!==null).map(taxPeriod)]);return [...keys].filter(inPeriod).sort().reverse().map(p=>({period:p,incomes:data.taxes.filter(x=>x.month===p&&x.income!==null),payments:data.taxes.filter(x=>taxPeriod(x)===p&&x.amount!==null)}));}
 function taxesView(){const rows=taxGroups();return `<div class="row between"><h3>Самозанятость и налог</h3>${btn('tax','＋ Запись','class="primary"')}</div><p class="footnote">Строки и фильтр относятся к месяцу дохода. Дата оплаты налога может быть в следующем месяце. Для старых записей связь предполагается, пока вы не подтвердите её в форме.</p><div class="finance-grid-wrap"><table class="finance-grid zkh-tax-grid"><thead><tr><th>Месяц дохода</th><th>Доход</th><th>Налог за этот месяц</th><th>Дата оплаты налога</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><th>${monthName(x.period)} ${x.period.slice(0,4)}</th><td>${x.incomes.length?rub(sum(x.incomes,'income')):'—'}</td><td>${x.payments.length?rub(sum(x.payments,'amount')):'—'}${x.payments.some(p=>!taxConfirmed(p))?'<small>Связь предполагается</small>':''}</td><td>${x.payments.map(p=>formatDate(p.date)||'Дата не указана').join(', ')||'—'}</td><td>${btn('tax','Изменить',`data-period="${x.period}"`)}</td></tr>`).join('')||'<tr><td colspan="5">За выбранный период нет записей.</td></tr>'}</tbody></table></div>`;}

 function moreView(){return `<section class="panel"><div class="row between"><h3>Объекты</h3>${btn('object','＋ Объект','class="primary"')}</div>${data.objects.map(o=>`<div class="fin-line"><span>${esc(o.name)}${o.archived?' · архив':''}</span>${btn('object','Изменить',`data-id="${o.id}"`)}</div>`).join('')}</section><section class="panel"><h3>История и резервные копии</h3><p class="footnote">История ЖКХ хранится отдельно от «Работы» и «Дохода». Перед импортом сервер сохраняет резервную копию.</p><label class="field">Перенести подготовленную историю<input id="zkh-import" type="file" accept=".json,application/json"></label>${btn('export','Скачать резервную копию','class="secondary"')}${data.importMeta?btn('rollback','Отменить импорт','class="textlink"'):''}</section><section class="panel"><h3>Проверка исходных данных</h3><p class="footnote">Неоднозначные значения сохранены для уточнения. Ошибки итоговых формул не заменены нулями.</p>${data.warnings.map(x=>`<div class="fin-entry"><div><strong>${esc(x.sheet)} · ${esc(x.cell)}</strong><p>${esc(x.message)}</p><p class="muted">${esc(x.raw)}</p></div></div>`).join('')||'<p class="muted">Замечаний нет.</p>'}</section>${data.audit?`<section class="panel"><h3>Сверка при переносе</h3><p class="footnote">Сравнение исходных годовых итогов с перенесёнными платежами. Комиссии учитываются отдельно. Последующие исправления не меняют эту исходную сверку.</p><div class="finance-grid-wrap"><table class="finance-grid"><thead><tr><th>Лист / год</th><th>Excel</th><th>По платежам</th><th>Разница</th></tr></thead><tbody>${data.audit.map(x=>`<tr><th>${esc(x.sheet)} · ${x.year}</th><td>${rub(x.excel)}</td><td>${rub(x.actual)}</td><td>${rub(x.difference)}</td></tr>`).join('')}</tbody></table></div></section>`:''}${data.sourceArchive?`<section class="panel"><h3>Исходник Excel</h3><p class="footnote">Все исходные листы, значения и формулы сохранены в резервной копии раздела.</p><p>${Object.keys(data.sourceArchive).map(esc).join(', ')}</p></section>`:''}`;}
 function render(){const years=[...new Set([Number(current().slice(0,4)),...(data.importMeta?.years||[]),...data.payments.map(x=>Number(x.month.slice(0,4))),...data.readings.map(x=>Number(x.month.slice(0,4)))])].sort((a,b)=>b-a);root.innerHTML=`<header class="topbar"><a class="brand" href="/">Свои деньги.</a><a href="/">Все разделы</a></header><main class="fin-main zkh-main"><div class="heading"><div><p class="muted">Квартиры, услуги и подписки</p><h1>ЖКХ</h1></div></div><nav class="fin-nav" aria-label="Разделы ЖКХ">${[['overview','Обзор'],['objects','Квартиры'],['services','Сервисы'],['taxes','Налоги'],['more','Ещё']].map(([k,l])=>btn('tab',l,`data-tab="${k}" class="${tab===k?'selected':''}"`)).join('')}</nav>${tab!=='more'?`<div class="zkh-filters"><label>Год<select id="zkh-year">${years.map(y=>`<option ${y===year?'selected':''}>${y}</option>`).join('')}</select></label><label>Период<select id="zkh-month"><option value="all" ${month==='all'?'selected':''}>Весь год</option>${Array.from({length:12},(_,i)=>{const m=String(i+1).padStart(2,'0');return `<option value="${m}" ${m===month?'selected':''}>${monthName(year+'-'+m)}</option>`;}).join('')}</select></label>${tab==='objects'?`<label>Квартира<select id="zkh-object">${[...data.objects].sort((a,b)=>Number(a.archived)-Number(b.archived)).map(o=>`<option value="${o.id}" ${o.id===objectId?'selected':''}>${esc(o.name)}${o.archived?' · архив':''}</option>`).join('')}</select></label>`:''}</div>`:''}${['objects','services'].includes(tab)?`<div class="zkh-view-toggle">${btn('view','Таблица',`data-view="table" class="${view==='table'?'selected':''}"`)}${btn('view','Карточки',`data-view="cards" class="${view==='cards'?'selected':''}"`)}</div>`:''}${tab==='objects'?`<nav class="finance-subnav">${btn('mode','Платежи',`data-mode="payments" class="${mode==='payments'?'selected':''}"`)}${btn('mode','Счётчики',`data-mode="meters" class="${mode==='meters'?'selected':''}"`)}</nav>`:''}${notice?`<p class="footnote" role="status">${esc(notice)}</p>`:''}<p class="error zkh-error" role="alert">${esc(error)}</p>${tab==='overview'?overview():tab==='objects'?mode==='meters'?metersView():paymentsView(objectId):tab==='services'?paymentsView('services'):tab==='taxes'?taxesView():moreView()}</main>`;
  for(const [id,apply,old]of [['zkh-year',v=>year=Number(v),year],['zkh-month',v=>month=v,month],['zkh-object',v=>objectId=v,objectId]])root.querySelector('#'+id)?.addEventListener('change',e=>{if(dirty){e.target.value=old;root.querySelector('.zkh-error').textContent='Сохраните или отмените изменения.';return;}apply(e.target.value);notice='';render();});
  root.querySelector('#zkh-import')?.addEventListener('change',async e=>{try{const value=JSON.parse(await e.target.files[0].text());if(!['money-zkh-import-v1','money-zkh-backup-v1'].includes(value.format))throw Error('Выберите подготовленный файл истории ЖКХ.');if(value.format==='money-zkh-backup-v1')value.data.importMeta={id:'restore-'+Date.now(),filename:'Резервная копия'};form('Перенести историю ЖКХ',`<p>Объектов: ${value.data.objects.length}. Оплат: ${value.data.payments.length}. Показаний: ${value.data.readings.length}. Данные этого раздела будут заменены; текущая версия сохранится в резервной копии.</p>`,'Перенести',async()=>{await persist(value.data,'/api/zkh/import');});}catch(err){error=err.message;render();}});
 }
 function paymentForm(id,owner,service){const x=data.payments.find(r=>r.id===id),choices=services(owner||data.services.find(s=>s.id===(x?.serviceId||service))?.objectId||objectId);form(x?'Изменить оплату':'Добавить оплату',`<label class="field">Услуга<select name="serviceId">${choices.map(s=>`<option value="${s.id}" ${s.id===(x?.serviceId||service)?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label>`+field('За какой месяц','month',x?.month||`${year}-${month==='all'?current().slice(5):month}`,'month','required')+field('Сумма, ₽ · можно оставить пустой','amount',x?.amount===null?'':x?x.amount/100:'','text','inputmode="decimal"')+field('Комиссия, ₽','commission',x?.commission==null?'':x.commission/100,'text','inputmode="decimal"')+field('Дата оплаты · можно оставить пустой','date',x?.date||'','date')+field('Комментарий','note',x?.note||'','text','maxlength="1000"'),'Сохранить',async(f,next)=>{const row={id:x?.id||uid(),serviceId:f.get('serviceId'),month:f.get('month'),amount:(x?.adjustment?signedMoney:money)(f.get('amount')),commission:(x?.adjustment?signedMoney:money)(f.get('commission')),date:f.get('date'),note:f.get('note')};if(!row.serviceId)throw Error('Сначала добавьте услугу.');const old=next.payments.find(r=>r.id===row.id);if(old)Object.assign(old,row);else next.payments.push(row);await persist(next);});}
 async function saveGrid(){const next=structuredClone(data);if(root.querySelector('.zkh-payment-grid'))for(const tr of root.querySelectorAll('.zkh-payment-grid tbody tr')){
  const period=tr.dataset.period;for(const sid of new Set([...tr.querySelectorAll('[data-payment]')].map(e=>e.dataset.payment))){const fields=[...tr.querySelectorAll('[data-payment]')].filter(e=>e.dataset.payment===sid),find=k=>fields.find(e=>e.dataset.field===k);if(fields.every(e=>e.value===e.dataset.original))continue;const a=money(find('amount').value),c=money(find('commission').value),date=find('date').value;if(date&&!validDate(date))throw Error('Проверьте дату оплаты.');const rows=next.payments.filter(x=>x.serviceId===sid&&x.month===period);if(rows.length<=1){const row=rows[0]||{id:uid(),serviceId:sid,month:period,note:''};Object.assign(row,{amount:a,commission:c,date});if(!rows.length)next.payments.push(row);}else{if(a===null)throw Error('Сумму нескольких оплат исправляйте в истории.');const originals=rows.filter(x=>!x.adjustment),old=rows.find(x=>x.adjustment),row=old||{id:uid(),serviceId:sid,month:period,date:'',note:'Корректировка месячного итога',adjustment:true};row.amount=a-sum(originals,'amount');row.commission=c===null?null:c-sum(originals,'commission');if(!old)next.payments.push(row);}}
 }else if(root.querySelector('.zkh-meter-grid'))for(const tr of root.querySelectorAll('.zkh-meter-grid tbody tr'))for(const mid of new Set([...tr.querySelectorAll('[data-meter]')].map(e=>e.dataset.meter))){const fields=[...tr.querySelectorAll('[data-meter]')].filter(e=>e.dataset.meter===mid);if(fields.every(e=>e.value===e.dataset.original))continue;const value=num(fields.find(e=>e.dataset.field==='value').value),date=fields.find(e=>e.dataset.field==='date').value;if(value===null)throw Error('Для исправления показания укажите число.');if(date&&!validDate(date))throw Error('Проверьте дату передачи.');const old=readings(mid,tr.dataset.period)[0],row=next.readings.find(x=>x.id===old?.id)||{id:uid(),meterId:mid,month:tr.dataset.period,note:''};row.value=value;row.date=date;if(!old)next.readings.push(row);}
  await persist(next);
 }
 root.addEventListener('input',e=>{if(e.target.closest('.zkh-payment-grid,.zkh-meter-grid'))mark();});
 root.addEventListener('keydown',e=>{if(e.key==='Escape'&&e.target.closest('.zkh-payment-grid,.zkh-meter-grid')){e.target.value=e.target.dataset.original;mark();}});
 root.addEventListener('click',async e=>{const b=e.target.closest('[data-zkh]');if(!b||busy)return;const action=b.dataset.zkh;if(dirty&&!['save','cancel'].includes(action)){root.querySelector('.zkh-error').textContent='Сохраните или отмените изменения.';return;}try{
  if(action==='cancel'){dirty=false;error='';render();return;}if(action==='save'){busy=true;b.disabled=true;await saveGrid();return;}
  if(action==='tab'){tab=b.dataset.tab;notice='';render();}else if(action==='mode'){mode=b.dataset.mode;render();}else if(action==='view'){view=b.dataset.view;render();}else if(action==='open-object'){objectId=b.dataset.id;tab='objects';mode='payments';render();}
  else if(action==='new-payment'||action==='edit-payment')paymentForm(b.dataset.id,b.dataset.owner,b.dataset.service);
  else if(action==='history'){const rows=paymentRows(b.dataset.service,b.dataset.period);form('Оплаты за '+esc(b.dataset.period),rows.map(x=>`<div class="fin-line"><span>${formatDate(x.date)||'Дата не указана'} · ${esc(x.note||'')}</span><b>${rub(x.amount)} + ${rub(x.commission)}</b></div>`).join('')+'<p class="footnote">Изменение отдельных записей доступно в режиме «Карточки», в истории услуги.</p>','Закрыть',async()=>{});}
  else if(action==='reading'){const x=b.dataset.id?data.readings.find(r=>r.id===b.dataset.id):readings(b.dataset.meter,b.dataset.period)[0];form('Показание счётчика',field('Показание','value',x?.value??'','text','inputmode="decimal" required')+field('Дата передачи','date',x?.date||'','date')+field('Комментарий','note',x?.note||'','text','maxlength="1000"'),'Сохранить',async(f,next)=>{const value=num(f.get('value'));if(value===null)throw Error('Введите показание.');const row={id:x?.id||uid(),meterId:b.dataset.meter,month:b.dataset.period,value,date:f.get('date'),note:f.get('note')},old=next.readings.find(r=>r.id===row.id);if(old)Object.assign(old,row);else next.readings.push(row);await persist(next);});}
  else if(action==='object'){const x=data.objects.find(o=>o.id===b.dataset.id);form(x?'Настройки объекта':'Добавить объект',field('Название','name',x?.name||'','text','required maxlength="200"')+field('Подпись / адрес','label',x?.label||'','text','maxlength="200"')+`<label class="check"><input name="archived" type="checkbox" ${x?.archived?'checked':''}>Архивный объект</label>`,'Сохранить',async(f,next)=>{const row={id:x?.id||uid(),name:f.get('name').trim(),label:f.get('label'),archived:f.has('archived')},old=next.objects.find(o=>o.id===row.id);if(old)Object.assign(old,row);else next.objects.push(row);await persist(next);});}
  else if(action==='new-service')form('Добавить услугу',field('Название','name','','text','required maxlength="200"')+`<label class="field">Раздел<select name="kind"><option value="utility">Коммунальная услуга</option><option value="service">Связь или подписка</option></select></label>`,'Добавить',async(f,next)=>{next.services.push({id:uid(),objectId:b.dataset.owner||objectId,name:f.get('name').trim(),kind:f.get('kind'),autopay:false});await persist(next);});
  else if(action==='new-meter')form('Добавить счётчик',field('Название · например Холодная вода 1','name','','text','required maxlength="200"')+field('Единица измерения','unit','м³','text','required'),'Добавить',async(f,next)=>{next.meters.push({id:uid(),objectId,name:f.get('name').trim(),unit:f.get('unit')});await persist(next);});
  else if(action==='tax'){const period=b.dataset.period||current(),income=data.taxes.find(x=>x.month===period&&x.income!==null),payment=data.taxes.find(x=>taxPeriod(x)===period&&x.amount!==null);form('Доход и налог за месяц',field('Месяц дохода','month',period,'month','required')+field('Доход, ₽','income',income?.income==null?'':income.income/100,'text','inputmode="decimal"')+field('Налог за месяц','taxIncomeMonth',period,'month','required')+field('Оплаченный налог, ₽','amount',payment?.amount==null?'':payment.amount/100,'text','inputmode="decimal"')+field('Дата оплаты налога','date',payment?.date||'','date')+field('Комментарий к оплате','note',payment?.note||'','text','maxlength="1000"'),'Сохранить',async(f,next)=>{const month=f.get('month'),incomeValue=money(f.get('income')),taxValue=money(f.get('amount'));let i=next.taxes.find(x=>x.id===income?.id);if(i)i.income=incomeValue;else if(incomeValue!==null){i={id:uid(),month,income:incomeValue,amount:null,date:'',note:''};next.taxes.push(i);}if(i)i.month=month;let pay=next.taxes.find(x=>x.id===payment?.id);if(!pay&&taxValue!==null){pay={id:uid(),month:f.get('date')?.slice(0,7)||month,income:null};next.taxes.push(pay);}if(pay)Object.assign(pay,{taxIncomeMonth:f.get('taxIncomeMonth'),amount:taxValue,date:f.get('date'),note:f.get('note')});await persist(next);});}

  else if(action==='export')download({format:'money-zkh-backup-v1',data},'zkh-backup.json');
  else if(action==='rollback')form('Отменить импорт','<p>Вернётся состояние ЖКХ перед последним импортом. Текущая версия сохранится в отдельной резервной копии.</p>','Отменить импорт',async()=>{download({format:'money-zkh-backup-v1',data},'zkh-before-rollback.json');await persist(undefined,'/api/zkh/rollback',{importId:data.importMeta.id});});
 }catch(err){error=err.message;root.querySelector('.zkh-error').textContent=error;}finally{busy=false;b.disabled=false;}});
 window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});desktop.addEventListener('change',()=>{if(!dirty)render();});render();
}
